% 雙邊角頻率傅立葉轉換，反轉換係數為 1/(2*pi)
functionId = 'rectangle'; % exponential、gaussian 或 rectangle
a = 1; A = 2; T = 3; % 固定函數的參數
omega = 0; % 角頻率 rad/s；普通頻率 Hz = omega/(2*pi)
validateattributes(omega,{'double'},{'scalar','real','finite'});
switch functionId
    case 'exponential'
        validateattributes(a,{'double'},{'scalar','real','finite','positive'});
        F = 2*a/(a^2+omega^2);
        kernel = @(t) exp(-a*abs(t)).*exp(-1i*omega*t);
        Fq = integral(kernel,-Inf,0,'AbsTol',1e-10,'RelTol',1e-9) ...
            + integral(kernel,0,Inf,'AbsTol',1e-10,'RelTol',1e-9); % 分段處理絕對值
    case 'gaussian'
        validateattributes(a,{'double'},{'scalar','real','finite','positive'});
        F = (sqrt(pi)/sqrt(a))*exp(-(omega/(2*sqrt(a)))^2);
        kernel = @(t) exp(-a*t.^2).*exp(-1i*omega*t);
        Fq = integral(kernel,-Inf,Inf,'AbsTol',1e-10,'RelTol',1e-9);
    case 'rectangle'
        validateattributes(A,{'double'},{'scalar','real','finite'});
        validateattributes(T,{'double'},{'scalar','real','finite','positive'});
        if omega == 0
            F = A*T; % 使用極限，絕不計算 0/0
        else
            z = omega*T/2; % 使用未正規化 sin(z)/z
            if ~isfinite(z), error('Fourier:NonFinite','相位數值溢位。'); end
            if abs(z) < 1e-4
                sincValue = 1-z^2/6+z^4/120; % 小參數級數
            else
                sincValue = sin(z)/z;
            end
            F = A*T*sincValue;
        end
        kernel = @(t) A*ones(size(t)).*exp(-1i*omega*t);
        Fq = integral(kernel,-T/2,T/2,'AbsTol',1e-10,'RelTol',1e-9);
    otherwise
        error('Fourier:Function','不支援此函數。');
end
if ~isfinite(F), error('Fourier:NonFinite','解析結果超出數值範圍。'); end
magnitude = abs(F); % 幅度非負，F 本身可能為負
difference = abs(F-Fq); % 與獨立積分比較
assert(isfinite(difference) && difference <= 1e-8*max(1,abs(F)));
fprintf('omega = %.12g rad/s；F = %.12g；幅度 = %.12g\n',omega,F,magnitude);
fprintf('積分核對誤差 %.3e\n',difference);
% MATLAB sinc(u)=sin(pi*u)/(pi*u)；不可直接誤用 sinc(omega*T/2)
